/* ГОЛОВОЛОМКИ НА КЛЕТКАХ: пятнашки, «Погасите свет», «Заливка», лабиринт, Сокобан.
   Поле — сам лист с B3. В пятнашках, свете и заливке ход — щелчок по клетке
   (плагин ловит смену выделения и отводит курсор на стоянку A2). В лабиринте
   и Сокобане герой — сам курсор таблицы: стрелки двигают его, плагин не пускает
   в стены и толкает ящики; щелчок по дальней клетке — пройти туда, если путь есть.
   Партия хранится в памяти листа. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

/* Свои уровни Сокобана: построены обратным ходом от решённого положения и проверены
   поиском в ширину; число — толчков в кратчайшем решении. # стена, . цель, $ ящик,
   * ящик на цели, @ грузчик, - снаружи. */
const СОКОБАН = [["####---/#. ####/#   $ #/#    .#/# $  @#/##    #/-######", 8], ["-####--/##  ###/#. $  #/#   $ #/##. @##/-#####-", 7], ["-####---/##  #---/#  $####/#..    #/###  $@#/--#   ##/--#####-", 9], ["#######/#     #/#  .  #/#   $@#/#   $##/#.   #-/######-", 8], ["####----/#  #####/# $$@$ #/#    . #/# .    #/####   #/---#.  #/---#####", 16], ["--######/###@.  #/#  .$$ #/#.   ###/#   $ #-/#     #-/#######-", 11], ["-#######/##    .#/# .  @ #/# $    #/# $    #/##$   ##/-#   .#-/-######-", 14], ["---#####/-###   #/-# $$$ #/##    @#/#      #/#.. .  #/#   ####/#####---", 16], ["########-/#      #-/#     $##/# @  $$ #/#  .    #/#   #   #/#   #####/#.. #----/#####----", 23], ["----####-/#####  #-/# $  @ ##/#  $    #/#  $ .. #/###    .#/--#######", 18], ["----######/#####    #/#       .#/# @  .   #/#.$ .$ $ #/#$ #######/#  #------/####------", 29], ["---####--/#### @#--/#   $$###/#   $ $ #/### .  .#/#.   #  #/#  .#####/#   #----/#   #----/#####----", 23]];

const Р0 = 2, С0 = 1, СТОЯНКА = {r: 1, c: 0};
const ПАМЯТЬ = 'головоломка';
const ТЁМНАЯ = '#151c2e', СТЕНА = '#2b3445', СИНЯЯ = '#296DF4';
const ЦВЕТА = ['#e5484d', '#f5c400', '#30a46c', '#0091ff', '#8e4ec6', '#f76b15'];
const ЦЕНТР = {align: 'center', valign: 'middle'};

const ВСЕ = ['Пятнашки 3×3', 'Пятнашки 4×4', 'Пятнашки 5×5', 'Погасите свет 5×5', 'Погасите свет 7×7',
  'Заливка 12×12', 'Заливка 16×16', 'Лабиринт 10×10', 'Лабиринт 20×15', 'Лабиринт 30×20']
  .concat(СОКОБАН.map((у, i) => 'Сокобан · уровень ' + (i + 1)));
function разобратьВыбор(подпись){
  let m;
  if((m = /^Пятнашки (\d)×/.exec(подпись))) return {вид: 'пятнашки', n: +m[1]};
  if((m = /^Погасите свет (\d)×/.exec(подпись))) return {вид: 'свет', n: +m[1]};
  if((m = /^Заливка (\d+)×/.exec(подпись))) return {вид: 'заливка', n: +m[1]};
  if((m = /^Лабиринт (\d+)×(\d+)/.exec(подпись))) return {вид: 'лабиринт', w: +m[1], h: +m[2]};
  if((m = /^Сокобан · уровень (\d+)/.exec(подпись))) return {вид: 'сокобан', уровень: +m[1] - 1};
  return null;
}

let игра = null, сНачала = 0, тик = null;
const случай = n => Math.floor(Math.random() * n);
function прошло(){ return игра && !игра.конец && сНачала ? Math.floor((Date.now() - сНачала) / 1000) : (игра ? игра.секунд || 0 : 0); }
function сохранить(){ лист(игра.лист).запомнить(ПАМЯТЬ, Object.assign({}, игра, {секунд: прошло()})); }
function часы(вкл){
  if(вкл && !тик) тик = setInterval(показатьСчёт, 1000);
  if(!вкл && тик){ clearInterval(тик); тик = null; }
}

/* ===== раскладка: плитки с зазорами (рамки у залитых клеток не видны — зазор их заменяет) ===== */
const плиткаR = r => Р0 + 2 * r, плиткаC = c => С0 + 2 * c;
function размерыПлиток(n, точек, зазор){
  for(let k = 0; k < n; k++){
    ширинаСтолбца(плиткаC(k), точек); высотаСтроки(плиткаR(k), точек);
    if(k < n - 1){ ширинаСтолбца(плиткаC(k) + 1, зазор); высотаСтроки(плиткаR(k) + 1, зазор); }
  }
}
/* клетка листа → плитка (или null, если зазор или мимо) */
function плиткаПо(r, c, n){
  const rr = r - Р0, cc = c - С0;
  if(rr < 0 || cc < 0 || rr % 2 || cc % 2) return null;
  const pr = rr / 2, pc = cc / 2;
  return pr < n && pc < n ? {r: pr, c: pc} : null;
}

/* ===== ПЯТНАШКИ ===== */
function новыеПятнашки(n){
  let п;
  do {
    п = Array.from({length: n * n}, (_, i) => (i + 1) % (n * n));
    for(let i = п.length - 1; i > 0; i--){ const j = случай(i + 1); [п[i], п[j]] = [п[j], п[i]]; }
    /* решаемость: чётность перестановки + (для чётного n) ряд пустой клетки */
    let инв = 0; const м = п.filter(x => x);
    for(let i = 0; i < м.length; i++) for(let j = i + 1; j < м.length; j++) if(м[i] > м[j]) инв++;
    const рядПустой = Math.floor(п.indexOf(0) / n);
    const решаема = n % 2 ? инв % 2 === 0 : (инв + (n - 1 - рядПустой)) % 2 === 0;
    if(!решаема){ const a = п.findIndex(x => x), b = п.findIndex((x, i) => x && i !== a); [п[a], п[b]] = [п[b], п[a]]; }
  } while(пятнашкиСобраны(п));
  return {n, плитки: п};
}
const пятнашкиСобраны = п => п.every((x, i) => x === (i + 1) % п.length);
function рисоватьПятнашку(i){
  const n = игра.n, x = игра.плитки[i], к = клетка(плиткаR(Math.floor(i / n)), плиткаC(i % n));
  if(!x){ к.значение = ''; к.стиль = {fill: null}; return; }
  const наМесте = x === i + 1;
  к.значение = x;
  к.стиль = Object.assign({b: 1, size: n > 4 ? 14 : 16, fill: игра.конец ? '#cfe9da' : наМесте ? '#dfe9fc' : '#c8d6f2', color: ТЁМНАЯ}, ЦЕНТР);
}
function ходПятнашки(r, c){
  const n = игра.n, пусто = игра.плитки.indexOf(0), пr = Math.floor(пусто / n), пc = пусто % n;
  if((r !== пr && c !== пc) || (r === пr && c === пc)) return;
  /* сдвигаем ряд плиток от выбранной к пустой */
  const шаг = r === пr ? (c < пc ? -1 : 1) : (r < пr ? -n : n);
  let i = пусто; const цель = r * n + c;
  const изм = [];
  while(i !== цель){ const j = i + шаг; игра.плитки[i] = игра.плитки[j]; игра.плитки[j] = 0; изм.push(i, j); i = j; игра.ходов++; }
  if(пятнашкиСобраны(игра.плитки)){ победа(); return; }
  for(const k of new Set(изм)) рисоватьПятнашку(k);
}

/* ===== ПОГАСИТЕ СВЕТ ===== */
function соседиСвета(i, n){ const r = Math.floor(i / n), c = i % n, out = [i];
  if(r > 0) out.push(i - n); if(r < n - 1) out.push(i + n); if(c > 0) out.push(i - 1); if(c < n - 1) out.push(i + 1); return out; }
function новыйСвет(n){
  const свет = new Array(n * n).fill(0);
  while(свет.every(x => !x)) for(let k = 0; k < Math.round(n * n / 3); k++) for(const j of соседиСвета(случай(n * n), n)) свет[j] ^= 1;
  return {n, свет, подсказка: null};
}
function рисоватьСвет(i){
  const n = игра.n, к = клетка(плиткаR(Math.floor(i / n)), плиткаC(i % n)), вкл = игра.свет[i];
  к.значение = игра.подсказка === i ? '◎' : '';
  к.стиль = Object.assign({fill: вкл ? '#f5c542' : СТЕНА, color: вкл ? ТЁМНАЯ : '#f5c542', b: 1, size: 16}, ЦЕНТР);
}
function ходСвет(r, c){
  const n = игра.n, i = r * n + c, было = игра.подсказка;
  игра.подсказка = null;
  for(const j of соседиСвета(i, n)) игра.свет[j] ^= 1;
  игра.ходов++;
  if(игра.свет.every(x => !x)){ победа(); return; }
  for(const j of соседиСвета(i, n)) рисоватьСвет(j);
  if(было !== null && было !== undefined) рисоватьСвет(было);
}
/* Решение «света» — линейная система по модулю 2 (метод Гаусса); из всех решений берём самое короткое. */
function решитьСвет(свет, n){
  const N = n * n, A = [];
  for(let i = 0; i < N; i++){ const ряд = new Array(N + 1).fill(0); for(const j of соседиСвета(i, n)) ряд[j] = 1; ряд[N] = свет[i]; A.push(ряд); }
  const опора = []; let р = 0;
  for(let c = 0; c < N && р < N; c++){
    let k = р; while(k < N && !A[k][c]) k++;
    if(k === N) continue;
    [A[р], A[k]] = [A[k], A[р]];
    for(let i = 0; i < N; i++) if(i !== р && A[i][c]) for(let j = c; j <= N; j++) A[i][j] ^= A[р][j];
    опора.push(c); р++;
  }
  for(let i = р; i < N; i++) if(A[i][N]) return null;
  const свободные = []; for(let c = 0; c < N; c++) if(!опора.includes(c)) свободные.push(c);
  let лучшее = null;
  for(let маска = 0; маска < (1 << свободные.length); маска++){
    const x = new Array(N).fill(0);
    свободные.forEach((c, k) => { x[c] = (маска >> k) & 1; });
    опора.forEach((c, i) => { let v = A[i][N]; for(const f of свободные) if(A[i][f]) v ^= x[f]; x[c] = v; });
    const вес = x.reduce((a, b) => a + b, 0);
    if(!лучшее || вес < лучшее.вес) лучшее = {x, вес};
  }
  return лучшее;
}

/* ===== ЗАЛИВКА ===== */
function областьЗаливки(цвет, n){
  const c0 = цвет[0], видно = new Set([0]), оч = [0];
  while(оч.length){ const i = оч.pop(), r = Math.floor(i / n), c = i % n;
    for(const j of [r > 0 ? i - n : -1, r < n - 1 ? i + n : -1, c > 0 ? i - 1 : -1, c < n - 1 ? i + 1 : -1])
      if(j >= 0 && !видно.has(j) && цвет[j] === c0){ видно.add(j); оч.push(j); } }
  return видно;
}
function залить(цвет, n, новый){
  const обл = областьЗаливки(цвет, n);
  for(const i of обл) цвет[i] = новый;
  return обл;
}
/* Предел ходов — сколько понадобилось жадному игроку (каждый раз берёт цвет, что захватывает больше всего):
   значит, уложиться можно всегда, а обыграть его — уже задача. */
function жадно(цвет, n){
  const ц = цвет.slice(); let ходов = 0;
  while(!ц.every(x => x === ц[0]) && ходов < 200){
    let лучший = -1, размер = -1;
    for(let k = 0; k < ЦВЕТА.length; k++){ if(k === ц[0]) continue; const т = ц.slice(); залить(т, n, k); const s = областьЗаливки(т, n).size; if(s > размер){ размер = s; лучший = k; } }
    залить(ц, n, лучший); ходов++;
  }
  return ходов;
}
function новаяЗаливка(n){
  const цвет = Array.from({length: n * n}, () => случай(ЦВЕТА.length));
  return {n, цвет, предел: жадно(цвет, n)};
}
const ПАЛИТРА_С = n => С0 + n + 1;
function рисоватьЗаливку(i){
  const n = игра.n, к = клетка(Р0 + Math.floor(i / n), С0 + i % n);
  к.значение = ''; к.стиль = {fill: ЦВЕТА[игра.цвет[i]]};
}
function рисоватьПалитру(){
  for(let k = 0; k < ЦВЕТА.length; k++){
    const к = клетка(Р0 + k * 2, ПАЛИТРА_С(игра.n));
    к.значение = k === игра.цвет[0] ? '●' : '';
    к.стиль = Object.assign({fill: ЦВЕТА[k], color: '#ffffff', size: 12, b: 1}, ЦЕНТР);
  }
}
function ходЗаливка(r, c){
  const n = игра.n;
  let k = null;
  if(r >= Р0 && r < Р0 + n && c >= С0 && c < С0 + n) k = игра.цвет[(r - Р0) * n + (c - С0)];
  else if(c === ПАЛИТРА_С(n) && (r - Р0) % 2 === 0 && (r - Р0) / 2 < ЦВЕТА.length && r >= Р0) k = (r - Р0) / 2;
  if(k === null || k === игра.цвет[0]) return;
  const обл = залить(игра.цвет, n, k);
  игра.ходов++;
  /* перекрашиваем всю новую область: прежняя сменила цвет, захваченные соседи — тоже её часть */
  for(const i of областьЗаливки(игра.цвет, n)) рисоватьЗаливку(i);
  рисоватьПалитру();
  if(игра.цвет.every(x => x === игра.цвет[0])){ победа(); return; }
  if(игра.ходов >= игра.предел){ поражение('Ходы кончились: предел ' + игра.предел + '. «Начать» — новое поле.'); }
}

/* ===== ЛАБИРИНТ ===== */
function новыйЛабиринт(w, h){
  const W = 2 * w + 1, H = 2 * h + 1, стены = new Array(W * H).fill(1);
  const до = (r, c) => r * W + c;
  /* поиск в глубину с возвратом: из клетки — в случайного непосещённого соседа, стену между ними сносим */
  const видно = new Set([0]), стек = [[0, 0]];
  стены[до(1, 1)] = 0;
  while(стек.length){
    const [r, c] = стек[стек.length - 1];
    const ходы = [[0, 1], [1, 0], [0, -1], [-1, 0]].filter(([dr, dc]) => { const rr = r + dr, cc = c + dc; return rr >= 0 && cc >= 0 && rr < h && cc < w && !видно.has(rr * w + cc); });
    if(!ходы.length){ стек.pop(); continue; }
    const [dr, dc] = ходы[случай(ходы.length)], rr = r + dr, cc = c + dc;
    видно.add(rr * w + cc);
