    if(было !== null && было !== undefined) рисоватьСвет(было);
    рисоватьСвет(i); сохранить();
    панель.сообщение('Нажмите клетку ◎. До конца — ' + р.вес + ' нажатий (порядок не важен).');
    return;
  }
  if(игра.вид === 'лабиринт'){
    const путь = путьЛ(игра.герой, игра.выход);
    игра.путь = путь ? путь.slice(1, -1) : [];
    for(const i of игра.путь) рисоватьЛабиринт(Math.floor(i / игра.W), i % игра.W);
    сохранить(); панель.сообщение('Путь к выходу отмечен точками — ' + (путь ? путь.length - 1 : 0) + ' шагов.');
    return;
  }
  if(игра.вид === 'заливка'){
    let лучший = -1, размер = -1;
    for(let k = 0; k < ЦВЕТА.length; k++){ if(k === игра.цвет[0]) continue; const т = игра.цвет.slice(); залить(т, игра.n, k); const s = областьЗаливки(т, игра.n).size; if(s > размер){ размер = s; лучший = k; } }
    панель.сообщение('Больше всего захватит ' + ['красный', 'жёлтый', 'зелёный', 'синий', 'фиолетовый', 'оранжевый'][лучший] + ' цвет (' + размер + ' клеток). Но жадный ход не всегда лучший.');
    return;
  }
  if(игра.вид === 'пятнашки'){ панель.сообщение('Совет: соберите сначала верхний ряд, потом левый столбец — и задача станет на ряд меньше. Последние два ряда собирайте по столбцам.'); return; }
  if(игра.вид === 'сокобан'){ панель.сообщение('Совет: ящик в углу без цели уже не вытащить — «Ход назад». Решение этого уровня — ' + игра.лучшее + ' толчков.'); return; }
}
function Правка(){
  const п = книга.повод;
  if(!игра || п.строение || п.откуда === 'плагин') return;
  const о = игра.область;
  const наПоле = (п.клетки || []).some(к => к.лист === игра.лист && к.строка - 1 >= 0 && к.строка - 1 <= о.r2 && к.столбец - 1 >= о.c1 && к.столбец - 1 <= о.c2);
  if(!наПоле) return;
  нарисоватьВсё();
  панель.сообщение('Поле правится только ходами — восстановил его.');
}
